import {Run,WIDTH,HEIGHT,clamp} from './engine.mjs';
import {CREW,ELEMENTS,FUSIONS,WORLDS} from './data.mjs';
import {Renderer} from './renderer.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='ronke-orbfall-v1';
const defaults={shards:0,totalKills:0,bestWave:0,runs:0,wins:0,meta:{vitality:0,power:0,reserves:0},lastCrew:'warrior',world:0,muted:true};
function readSave(){try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(!raw||typeof raw!=='object')return structuredClone(defaults);const result={...defaults,meta:{...defaults.meta}};for(const k of ['shards','totalKills','bestWave','runs','wins'])result[k]=Number.isFinite(raw[k])?clamp(Math.floor(raw[k]),0,1e8):0;for(const k of ['vitality','power','reserves'])result.meta[k]=Number.isFinite(raw.meta?.[k])?clamp(Math.floor(raw.meta[k]),0,3):0;result.lastCrew=CREW.some(c=>c.id===raw.lastCrew)?raw.lastCrew:'warrior';result.world=Number.isInteger(raw.world)?clamp(raw.world,0,2):0;result.muted=raw.muted!==false;return result}catch{return structuredClone(defaults)}}
let save=readSave(),selected=save.lastCrew,world=save.world,run=null,paused=false,settled=false,modalType='',modalDismissable=true,modalPauseBefore=false,modalFocus=null,starting=false;
const keys=new Set(),canvas=$('#arena'),renderer=new Renderer(canvas),input={moveX:0,moveY:0,aimX:300,aimY:150,shoot:true,dash:false,surge:false};
let autoFire=true,pointerHeld=false,lastAimTime=0,joystick={x:0,y:0,active:false},last=performance.now(),hudClock=0,toastTimer,bannerTimer,resultTimer;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(save))}catch{/* Storage can be unavailable in private browser contexts. Gameplay still works. */}updateSaveUI()}
function updateSaveUI(){$('#shards').textContent=save.shards;$('#best-wave').textContent=save.bestWave?'Depth '+String(save.bestWave).padStart(2,'0'):'Not yet explored';$('#total-kills').textContent=save.totalKills.toLocaleString()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700)}
function clock(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0')}
const audio={ctx:null,muted:save.muted,lastShot:0,unlock(){try{this.ctx??=new (window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume()}catch{}},tone(freq,duration=.08,kind='sine',volume=.035){if(this.muted||!this.ctx)return;try{const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=kind;o.frequency.value=freq;g.gain.setValueAtTime(volume,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+duration);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+duration)}catch{}},event(e){if(e.type==='shot'&&performance.now()-this.lastShot>90){this.lastShot=performance.now();this.tone(340,.035,'triangle',.012)}if(e.type==='kill')this.tone(500+Math.random()*180,.06,'sine',.018);if(e.type==='hurt')this.tone(110,.15,'triangle',.04);if(e.type==='level'||e.type==='surge'){this.tone(440,.15);setTimeout(()=>this.tone(660,.18),90);setTimeout(()=>this.tone(880,.2),180)}}};
function soundUI(){$('#sound').setAttribute('aria-label',audio.muted?'Enable sound':'Mute sound');$('#sound .off-dot').classList.toggle('enabled',!audio.muted)}
$('#sound').onclick=()=>{audio.unlock();audio.muted=!audio.muted;save.muted=audio.muted;persist();soundUI();if(!audio.muted)audio.tone(660,.1);toast(audio.muted?'Sound off':'Sound on')};

function selectCrew(id){selected=id;save.lastCrew=id;persist();const c=CREW.find(c=>c.id===id),e=ELEMENTS[c.element];$('#runner-image').src=`assets/portraits/${id}.png`;$('#runner-image').alt=c.name+', '+c.role;$('#runner-name').textContent=c.name;$('#runner-role').textContent=c.role.toUpperCase();$('#runner-tagline').textContent=c.tagline;$('#runner-perk').textContent=c.perk;$('#runner-element').textContent=e.name;$('#runner-orb').style.setProperty('--orb-color',e.color)}
function drawWorlds(){$('#worlds').innerHTML=WORLDS.map((w,i)=>`<button class="world-card ${world===i?'selected':''}" data-world="${i}" aria-pressed="${world===i}"><small>DESCENT / 0${i+1}</small><h3>${w.name}</h3><p>${['Your first step into the deep.','A little heat. A little more danger.','The far side of familiar.'][i]}</p><span class="world-check">${world===i?'✓':'↗'}</span></button>`).join('');$$('[data-world]').forEach(b=>b.onclick=()=>{world=Number(b.dataset.world);save.world=world;persist();drawWorlds()})}

function showModal(html,{type='info',dismissable=true,pauseGame=true}={}){
 if(modalType)hideModal(false);
 modalType=type;modalDismissable=dismissable;modalPauseBefore=paused;modalFocus=document.activeElement;
 if(pauseGame&&run)paused=true;
 $('#modal-content').innerHTML=html;$('#modal-close').hidden=!dismissable;$('#modal').hidden=false;document.body.style.overflow='hidden';
 setTimeout(()=>{const first=$('#modal-content button')||$('#modal-close');first?.focus()},0);
}
function hideModal(resume=true){if(!modalType)return;$('#modal').hidden=true;document.body.style.overflow='';if(resume)paused=modalPauseBefore;modalType='';if(modalFocus?.isConnected)modalFocus.focus()}
$('#modal-close').onclick=()=>hideModal();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')&&modalDismissable)hideModal()});
function criticalModal(){return ['upgrade','result'].includes(modalType)}
function openCrew(){if(criticalModal())return toast('Finish this choice first.');let preview=selected;
 const content=()=>`<p class="eyebrow">A DIFFERENT KIND OF FAMILY</p><h2 id="modal-title">Meet your crew.</h2><p class="dialog-description">23 gorillas. 23 ways to make a very bad decision. Everyone is available in this prototype.</p><div class="crew-grid">${CREW.map(c=>`<button class="crew-card ${preview===c.id?'selected':''}" data-crew="${c.id}" aria-pressed="${preview===c.id}"><span class="crew-dot" style="--orb-color:${ELEMENTS[c.element].color}"></span><img src="assets/portraits/${c.id}.png" alt="" loading="lazy"><b>${c.name}</b><small>${c.role}</small></button>`).join('')}</div><div class="crew-detail" id="crew-detail"></div>`;
 showModal(content(),{type:'crew'});
 const detail=()=>{const c=CREW.find(c=>c.id===preview);$('#crew-detail').innerHTML=`<div><h3>${c.name}</h3><p>${c.perk}</p></div><button class="primary-button" id="choose-crew">${run?'Save for next run':'Choose runner'} <span>↗</span></button>`;$('#choose-crew').onclick=()=>{selectCrew(preview);hideModal();toast(c.name+' is ready for the next descent.')};$$('[data-crew]').forEach(b=>{b.classList.toggle('selected',b.dataset.crew===preview);b.setAttribute('aria-pressed',b.dataset.crew===preview)})};
 $$('[data-crew]').forEach(b=>b.onclick=()=>{preview=b.dataset.crew;detail()});detail();
}
function openHelp(){if(criticalModal())return toast('Finish this choice first.');showModal(`<p class="eyebrow">A FEW WORDS BEFORE YOU FALL</p><h2 id="modal-title">The field guide.</h2><p class="dialog-description">Keep the ruins above the breach line. Make every wall work for you. Clear ten waves to finish the expedition.</p><div class="guide-grid"><div><h3>01 / Move & aim</h3><p><kbd>WASD</kbd> or arrow keys move your runner in the lower part of the pit. Move your pointer to aim. Orbs throw automatically by default; use the AUTO button to switch it off. With AUTO off, hold your pointer or <kbd>SPACE</kbd> to throw.</p></div><div><h3>02 / Keep bouncing</h3><p>Orbs bounce off walls and enemies, then return to your supply at the bottom. Elemental orbs burn, freeze, poison, chain, or explode. Enemy shots and breaches cost health. <kbd>SHIFT</kbd> dashes through danger.</p></div><div><h3>03 / Build your orbit</h3><p>Clearing enemies earns experience. Pick one of three upgrades when you level up. Combine Ember + Venom for Toxic Sun, Frost + Spark for Stormglass, or Light + Void for Eclipse. An evolution replaces its ingredients.</p></div><div><h3>04 / Let it all out</h3><p>Defeated enemies charge Rift Surge. Press <kbd>E</kbd> or its on-screen button when full for a burst of orbs and a brief shield. On touch devices, use the left stick to move, drag on the arena to aim, and tap DASH to dodge.</p></div></div><p class="dialog-description" style="margin-top:20px">Press <kbd>P</kbd> or <kbd>ESC</kbd> to pause. Your shards and basecamp improvements save on this device. Sound starts muted.</p><div class="dialog-actions"><button class="primary-button" id="guide-done">Got it <span>↘</span></button></div>`,{type:'help'});$('#guide-done').onclick=()=>hideModal()}
function openCamp(){if(criticalModal())return toast('Finish this choice first.');showModal(`<p class="eyebrow">A LITTLE STRONGER EVERY TIME</p><h2 id="modal-title">Home between falls.</h2><p class="dialog-description">Spend shards from your runs on permanent improvements. These take effect at the start of your next descent. You have <b>${save.shards} shards</b>.</p><div class="camp-grid">${[{id:'vitality',name:'Heartwood',icon:'♥',desc:'+10 starting health per rank.'},{id:'power',name:'Heavy lifting',icon:'↗',desc:'+5% starting orb damage per rank.'},{id:'reserves',name:'Deep pockets',icon:'◉',desc:'+1 starting orb charge per rank.'}].map(u=>{const rank=save.meta[u.id],cost=20+rank*25;return `<div class="camp-upgrade"><span class="upgrade-symbol" style="font-size:28px;color:var(--gold)">${u.icon}</span><h3>${u.name}</h3><p>${u.desc}</p><small>RANK ${rank} / 3</small><button class="primary-button" data-buy="${u.id}" ${rank>=3||save.shards<cost?'disabled':''}>${rank>=3?'Fully improved':'Improve'} <span>${rank>=3?'✓':'✦ '+cost}</span></button></div>`}).join('')}</div>`,{type:'camp'});$$('[data-buy]').forEach(b=>b.onclick=()=>{const id=b.dataset.buy,rank=save.meta[id],cost=20+rank*25;if(rank>=3||save.shards<cost)return;save.shards-=cost;save.meta[id]++;persist();hideModal();openCamp();toast('Basecamp improved. Your next run starts stronger.')})}
function openCredits(){if(criticalModal())return;showModal(`<p class="eyebrow">SMALL TEAM. VERY BIG PIT.</p><h2 id="modal-title">RONKE: Orbfall</h2><p class="dialog-description">A playable prototype built around your blue-gorilla character reference. All 23 crew members use the checked eight-frame sprite sets: idle, throw, walking, hurt, and seated defeat.</p><div class="guide-grid"><div><h3>In this build</h3><p>Ten waves, two bosses, three ruin themes, elemental effects, three orb evolutions, character perks, touch controls, optional synthesized sound, and local basecamp progression.</p></div><div><h3>Still a prototype</h3><p>The walking loop uses two contact poses. Characters have one illustrated facing direction. Enemy art is drawn in Canvas. It is an original fan prototype inspired by BALL x PIT, with no affiliation to the original creators.</p></div></div><p class="dialog-description" style="margin-top:20px">No account, payment, or streaming connection is required. Progress is stored in this browser.</p>`,{type:'credits'})}

async function startRun(){if(starting)return;starting=true;clearTimeout(resultTimer);audio.unlock();hideModal();paused=false;keys.clear();joystick={x:0,y:0,active:false};pointerHeld=false;input.dash=false;input.surge=false;input.aimX=300;input.aimY=100;autoFire=true;$('#autofire').setAttribute('aria-pressed','true');$('#autofire').innerHTML='AUTO <b>ON</b>';
 const c=CREW.find(c=>c.id===selected);renderer.load(c);try{await renderer.sprite.decode()}catch{toast('The character art could not load. Please refresh and try again.');starting=false;return}
 run=new Run({crewId:selected,world,meta:save.meta,seed:Math.floor(Math.random()*0xffffffff)});settled=false;renderer.particles=[];renderer.labels=[];renderer.rings=[];renderer.chains=[];
 $('#hub').hidden=true;$('#game').hidden=false;$('#game-world').textContent=WORLDS[world].name.toUpperCase();$('#game-runner-name').textContent=c.name;$('#game-runner-role').textContent=c.role;$('#game-portrait').src=`assets/portraits/${c.id}.png`;$('#game-perk').textContent=c.perk;$('#aim-hint').hidden=false;setTimeout(()=>{$('#aim-hint').hidden=true},9000);updateLoadout();updateHUD();canvas.focus();window.scrollTo({top:0,behavior:'auto'});starting=false;
 toast(matchMedia('(pointer: coarse)').matches?'Left stick to move · drag the arena to aim':'WASD to move · pointer to aim · Shift to dash');
}
$('#start-run').onclick=startRun;$('#hero-start').onclick=startRun;
function updateLoadout(){if(!run)return;$('#orb-count').textContent=String(run.elements.length).padStart(2,'0');$('#loadout').innerHTML=run.elements.map(t=>`<div class="loadout-item"><span class="orb-icon" style="--orb-color:${ELEMENTS[t].color}"></span><div><b>${ELEMENTS[t].name}</b><small>${FUSIONS.some(f=>f.id===t)?'EVOLVED':'ELEMENTAL ORB'}</small></div><span>Lv.${run.elementLevels[t]||1}</span></div>`).join('');$('#upgrade-list').innerHTML=run.picks.length?run.picks.map(p=>`<span>${p}</span>`).join(''):'<span class="muted">A fresh start.</span>'}
function updateHUD(){if(!run)return;const p=run.player;$('#health-text').textContent=Math.ceil(p.hp)+' / '+p.maxHp;$('#health-fill').style.width=clamp(p.hp/p.maxHp*100,0,100)+'%';$('#xp-fill').style.width=run.xp/run.xpNeed*100+'%';$('#level-text').textContent=run.level;$('#ammo-text').textContent=p.ammo+' / '+p.capacity;$('#wave-number').textContent=String(run.wave).padStart(2,'0');$('#run-time').textContent=clock(run.time);$('#run-kills').textContent=run.kills;$('#run-bounces').textContent=run.bounces;$('#run-combo').textContent=run.bestCombo+'×';$('#wave-label').textContent=run.wave===10?'The root of it all.':run.wave===5?'The gatekeeper is waiting.':'Keep the line clear.';$('#surge-fill').style.width=run.surge+'%';$('#surge-text').textContent=run.surge>=100?'[ E ]':Math.floor(run.surge)+'%';$('#surge-button').disabled=run.surge<100;$('#surge-button').firstChild.textContent=run.surge>=100?'Unleash surge ':'Charging ';$('#mobile-surge').disabled=run.surge<100;$('#mobile-surge').setAttribute('aria-label',run.surge>=100?'Unleash Rift Surge':'Rift Surge charging '+Math.floor(run.surge)+' percent')}
function showUpgrade(){const automatic=['cogitator','radical'].includes(run.crew.id);showModal(`<p class="eyebrow">LEVEL ${run.level} / A LITTLE MORE DANGEROUS</p><h2 id="modal-title">Choose your next advantage.</h2><p class="dialog-description">${automatic?run.crew.name+' is choosing for you. Thinking is part of the job.':'The pit can wait a moment. Pick one upgrade to continue your descent.'}</p><div class="upgrade-grid ${run.choices.length===4?'four':''}">${run.choices.map((u,i)=>`<button class="upgrade-card ${u.fusion?'evolution':''}" data-upgrade="${i}" ${automatic?'disabled':''}><kbd>${i+1}</kbd><span class="upgrade-symbol">${u.icon}</span><small>${u.kind}</small><h3>${u.name}</h3><p>${u.description}</p><span class="pick-label">TAKE UPGRADE ↗</span></button>`).join('')}</div>`,{type:'upgrade',dismissable:false,pauseGame:false});$$('[data-upgrade]').forEach(b=>b.onclick=()=>pickUpgrade(Number(b.dataset.upgrade)))}
function pickUpgrade(index){if(!run||run.phase!=='upgrade')return;if(run.chooseUpgrade(index)){hideModal();paused=false;updateLoadout();canvas.focus()}}
function settle(){if(!run||settled)return;settled=true;save.shards+=run.reward;save.totalKills+=run.kills;save.bestWave=Math.max(save.bestWave,run.wave);save.runs++;if(run.phase==='victory')save.wins++;persist()}
function showResult(){if(!run)return;const win=run.phase==='victory';settle();showModal(`<div class="result-content"><p class="eyebrow">${win?'THE PIT CAN KEEP ITS SECRETS. FOR NOW.':'THERE IS ALWAYS ANOTHER DESCENT.'}</p><img src="assets/portraits/${run.crew.id}${win?'':'_defeated'}.png" alt="${win?'Victorious':'Defeated'} ${run.crew.name}"><h2 id="modal-title">${win?'Back from the brink.':'A good run. A deep fall.'}</h2><p class="dialog-description">${win?'Ten waves. Two guardians. One very determined gorilla.':'The ruins won this round. Bring your shards home and come back a little stronger.'}</p><div class="result-stats"><div><b>${String(run.wave).padStart(2,'0')}</b><small>DEPTH REACHED</small></div><div><b>${run.kills}</b><small>ENEMIES CLEARED</small></div><div><b>+${run.reward}</b><small>SHARDS EARNED</small></div></div><p class="muted" style="font-size:11px">${clock(run.time)} in the pit · ${run.bestCombo}× best combo · ${run.bounces} wall bounces</p><div class="result-buttons"><button id="result-camp" class="secondary-button">Back to camp</button><button id="result-again" class="primary-button">One more descent <span>↘</span></button></div></div>`,{type:'result',dismissable:false});$('#result-again').onclick=startRun;$('#result-camp').onclick=goHome}
function goHome(){clearTimeout(resultTimer);hideModal();run=null;paused=false;keys.clear();$('#game').hidden=true;$('#hub').hidden=false;updateSaveUI();selectCrew(selected);window.scrollTo({top:0,behavior:'auto'})}
function askLeave(){if(!run)return goHome();if(['victory','defeat'].includes(run.phase))return goHome();if(modalType==='upgrade')return toast('Choose an upgrade before leaving the run.');showModal(`<p class="eyebrow">LIVE TO THROW ANOTHER DAY</p><h2 id="modal-title">Head back to basecamp?</h2><p class="dialog-description">Your current descent will end. You’ll bank the shards earned so far and keep your permanent progress.</p><div class="dialog-actions"><button class="secondary-button" id="stay">Keep descending</button><button class="primary-button" id="bank">Bank shards & leave <span>↗</span></button></div>`,{type:'leave'});$('#stay').onclick=()=>hideModal();$('#bank').onclick=()=>{run.finish(false);settle();goHome()}}
function togglePause(){if(!run||['victory','defeat'].includes(run.phase)||run.phase==='upgrade')return;if(modalType==='pause'){hideModal();return}if(modalType)return;showModal(`<p class="eyebrow">TAKE A BREATH</p><h2 id="modal-title">The pit can wait.</h2><p class="dialog-description">Your descent is paused. Nothing moves until you’re ready.</p><div class="dialog-actions"><button class="secondary-button" id="pause-leave">Back to basecamp</button><button class="primary-button" id="resume">Keep descending <span>↘</span></button></div>`,{type:'pause'});$('#resume').onclick=()=>{hideModal();canvas.focus()};$('#pause-leave').onclick=()=>{hideModal();askLeave()}}
$('#pause-button').onclick=togglePause;$('#leave-run').onclick=askLeave;$('#brand').onclick=()=>run?askLeave():goHome();
$$('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==='home')run?askLeave():goHome();if(a==='crew')openCrew();if(a==='camp')openCamp();if(a==='credits')openCredits()});$('#help').onclick=openHelp;$('#guide-link').onclick=openHelp;
function toggleAuto(){autoFire=!autoFire;$('#autofire').setAttribute('aria-pressed',autoFire);$('#autofire').innerHTML=`AUTO <b>${autoFire?'ON':'OFF'}</b>`;toast(autoFire?'Automatic throws on':'Hold pointer or Space to throw')}
$('#autofire').onclick=toggleAuto;$('#surge-button').onclick=()=>{input.surge=true};$('#mobile-surge').onclick=()=>{input.surge=true};$('#touch-dash').onpointerdown=e=>{e.preventDefault();input.dash=true};
function aim(e){const r=canvas.getBoundingClientRect(),w=Math.min(r.width,r.height*WIDTH/HEIGHT),h=w*HEIGHT/WIDTH;input.aimX=clamp((e.clientX-r.left-(r.width-w)/2)/w*WIDTH,0,WIDTH);input.aimY=clamp((e.clientY-r.top-(r.height-h)/2)/h*HEIGHT,20,HEIGHT-140);lastAimTime=performance.now()}
canvas.addEventListener('pointermove',e=>aim(e));canvas.addEventListener('pointerdown',e=>{aim(e);pointerHeld=true;canvas.setPointerCapture(e.pointerId);canvas.focus();e.preventDefault()});canvas.addEventListener('pointerup',()=>pointerHeld=false);canvas.addEventListener('pointercancel',()=>pointerHeld=false);
const stick=$('#joystick'),knob=$('#joystick-knob');function moveStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,d=Math.hypot(dx,dy),limit=28;joystick.x=dx/Math.max(limit,d);joystick.y=dy/Math.max(limit,d);knob.style.transform=`translate(${joystick.x*limit}px,${joystick.y*limit}px)`}stick.onpointerdown=e=>{joystick.active=true;stick.setPointerCapture(e.pointerId);moveStick(e);e.preventDefault()};stick.onpointermove=e=>{if(joystick.active)moveStick(e)};function resetStick(){joystick.active=false;joystick.x=joystick.y=0;knob.style.transform=''}stick.onpointerup=resetStick;stick.onpointercancel=resetStick;
document.addEventListener('keydown',e=>{
 if(modalType){if(e.key==='Escape'&&modalDismissable){e.preventDefault();hideModal();return}if(modalType==='upgrade'&&/^[1-4]$/.test(e.key)){pickUpgrade(Number(e.key)-1);return}if(e.key==='Tab'){const focusable=$$('#modal button:not([disabled]):not([hidden]),#modal a[href]');if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}return}
 if(!run)return;const key=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','shift','e','p','escape'].includes(key))e.preventDefault();if((key==='p'||key==='escape')&&!e.repeat){togglePause();return}keys.add(key);if(key==='shift'&&!e.repeat)input.dash=true;if(key==='e'&&!e.repeat)input.surge=true;
});
document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();pointerHeld=false;resetStick();if(run&&run.phase==='playing'&&!modalType)togglePause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();pointerHeld=false;if(run&&run.phase==='playing'&&!modalType)togglePause()}});
function handleEvents(){if(!run)return;for(const e of run.drain()){
 renderer.event(e);audio.event(e);
 if(e.type==='wave'){$('#wave-banner').innerHTML=(e.boss?'GUARDIAN AHEAD':'DEPTH '+String(e.wave).padStart(2,'0'))+`<small>${e.boss?'MAKE EVERY BOUNCE COUNT':WORLDS[run.world].name.toUpperCase()}</small>`;$('#wave-banner').classList.add('show');clearTimeout(bannerTimer);bannerTimer=setTimeout(()=>$('#wave-banner').classList.remove('show'),2100)}
 if(e.type==='level')showUpgrade();
 if(e.type==='upgrade'){if(modalType==='upgrade')hideModal();paused=false;updateLoadout();toast((e.fusion?'Evolution unlocked: ':'')+e.name)}
 if(e.type==='end'){settle();clearTimeout(resultTimer);resultTimer=setTimeout(showResult,750)}
}}
function frame(now){const dt=Math.min(.05,Math.max(0,(now-last)/1000));last=now;if(run&&!$('#game').hidden){
 input.moveX=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joystick.x;input.moveY=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joystick.y;
 if(matchMedia('(pointer: coarse)').matches&&now-lastAimTime>1800){const target=run.enemies.filter(e=>!e.dead).sort((a,b)=>b.y-a.y)[0];if(target){input.aimX=target.x;input.aimY=target.y}}
 input.shoot=autoFire||pointerHeld||keys.has(' ');if(!paused)run.advance(dt,input);input.dash=false;input.surge=false;handleEvents();renderer.draw(run,input,paused?0:dt);hudClock+=dt;if(hudClock>.09){hudClock=0;updateHUD()}
 }requestAnimationFrame(frame)}
updateSaveUI();selectCrew(selected);drawWorlds();soundUI();requestAnimationFrame(frame);
// Read-only diagnostics for reproducible QA. They do not change the run.
window.orbfall={get state(){return run?{phase:run.phase,crew:run.crew.id,wave:run.wave,kills:run.kills,balls:run.balls.length,health:run.player.hp,level:run.level,paused}:null},version:'0.1.0'};
